{"states": ["Established Dialog and Session", "INVITE Transaction in Progress (Client)", "INVITE Transaction in Progress (Server)", "Dialog Termination Pending"], "transitions": [
  {
    "from": "Established Dialog and Session",
    "event": "re-INVITE",
    "action": "send new INVITE request",
    "to": "INVITE Transaction in Progress (Client)"
  },
  {
    "from": "INVITE Transaction in Progress (Client)",
    "event": "non-2xx final response",
    "action": "remain unchanged",
    "to": "Established Dialog and Session"
  },
  {
    "from": "INVITE Transaction in Progress (Client)",
    "event": "481, 408, or timeout",
    "action": "terminate dialog",
    "to": "Dialog Termination Pending"
  },
  {
    "from": "INVITE Transaction in Progress (Client)",
    "event": "491",
    "action": "attempt re-INVITE after randomized interval",
    "to": "INVITE Transaction in Progress (Client)"
  },
  {
    "from": "Established Dialog and Session",
    "event": "re-INVITE",
    "action": "return 491",
    "to": "INVITE Transaction in Progress (Server)"
  },
  {
    "from": "INVITE Transaction in Progress (Server)",
    "event": "second INVITE with lower CSeq",
    "action": "return 500 with Retry-After",
    "to": "Established Dialog and Session"
  },
  {
    "from": "INVITE Transaction in Progress (Server)",
    "event": "incoming INVITE while sending INVITE",
    "action": "return 491",
    "to": "Established Dialog and Session"
  }
]}

